import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import '@kerfjs/ui/layout.css';
import './navigation.css';

type Route = 'overview' | 'projects' | 'members' | 'billing';
export function Navigation({ route, navigate, onHelp, onAccount }: {
  route: Route; navigate: (route: Route) => void;
  onHelp: () => void; onAccount: () => void;
}) {
  return <nav className="kui-layout kui-sidebar navigation" aria-label="Main navigation">
    <section className="kui-sidebar-section" aria-labelledby="work-heading">
      <MenuHeader id="work-heading" label="Work" />
      <MenuItem label="Overview" icon={<span aria-hidden="true">▦</span>} selected={route === 'overview'}
        aria-current={route === 'overview' ? 'page' : undefined} onClick={() => navigate('overview')} />
      <MenuItem label="Projects" selected={route === 'projects'}
        aria-current={route === 'projects' ? 'page' : undefined} onClick={() => navigate('projects')} />
    </section>
    <section className="kui-sidebar-section" aria-labelledby="team-heading">
      <MenuHeader id="team-heading" label="Team" />
      <MenuItem label="Members" icon={<span aria-hidden="true">♙</span>} selected={route === 'members'}
        aria-current={route === 'members' ? 'page' : undefined} onClick={() => navigate('members')} />
      <MenuItem label="Billing (unavailable)" disabled />
    </section>
    <section className="kui-sidebar-surface" aria-labelledby="workspace-summary">
      <h2 id="workspace-summary">Design workspace</h2>
      <p>12 projects · 6 members</p>
    </section>
    <footer className="navigation-footer" aria-label="Workspace actions">
      <button type="button" onClick={onHelp}>Help</button>
      <button type="button" onClick={onAccount}>Account</button>
    </footer>
  </nav>;
}
// Confirm component prop types with the package API during integration;
// frozen guidance provides component names, not their declarations.

