.navigation { display: flex; flex-direction: column; min-inline-size: 0; overflow-wrap: anywhere; }
.navigation-footer { margin-block-start: auto; display: flex; flex-wrap: wrap; }
.navigation-footer button { min-block-size: 2.75rem; }
.navigation :focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }
/* The single kui-sidebar gutter and public section/surface classes own
   navigation insets. No wrapper padding or private component selectors. */
